use crate::common::{
    eval_horner_f128_slice, eval_horner_f16_slice, eval_horner_f32_slice, eval_horner_f64_slice,
};

#[inline(always)]
fn k_simple_f64(x: f64) -> f64 {
    if x <= EXP_SEG_BOUNDS_F64[0] {
        eval_horner_f64_slice(x, &COEFFS64_SEG0)
    } else if x <= EXP_SEG_BOUNDS_F64[1] {
        eval_horner_f64_slice(x, &COEFFS64_SEG1)
    } else if x <= EXP_SEG_BOUNDS_F64[2] {
        eval_horner_f64_slice(x, &COEFFS64_SEG2)
    } else if x <= EXP_SEG_BOUNDS_F64[3] {
        eval_horner_f64_slice(x, &COEFFS64_SEG3)
    } else if x <= EXP_SEG_BOUNDS_F64[4] {
        eval_horner_f64_slice(x, &COEFFS64_SEG4)
    } else if x <= EXP_SEG_BOUNDS_F64[5] {
        eval_horner_f64_slice(x, &COEFFS64_SEG5)
    } else {
        eval_horner_f64_slice(x, &COEFFS64_SEG5)
    }
}
