#[inline(always)]
pub(crate) fn scale_pow2_f64(k: i32) -> f64 {
    if (-1022..=1023).contains(&k) {
        f64::from_bits(((k + 1023) as u64) << 52)
    } else if (-1074..=-1023).contains(&k) {
        f64::from_bits(1_u64 << (k + 1074))
    } else if k > 1023 {
        f64::INFINITY
    } else {
        0.0_f64
    }
}
#[inline(always)]
pub(crate) fn scale_pow2_f32(k: i32) -> f32 {
    if (-126..=127).contains(&k) {
        f32::from_bits(((k + 127) as u32) << 23)
    } else if (-149..=-127).contains(&k) {
        f32::from_bits(1_u32 << (k + 149))
    } else if k > 127 {
        f32::INFINITY
    } else {
        0.0_f32
    }
}
#[inline(always)]
fn scale_pow2_f128(k: i32) -> f128 {
    if (-16382..=16383).contains(&k) {
        f128::from_bits(((k + 16383) as u128) << 112)
    } else if (-16494..=-16383).contains(&k) {
        f128::from_bits(1_u128 << (k + 16494))
    } else if k > 16383 {
        f128::INFINITY
    } else {
        0.0_f128
    }
}
#[inline(always)]
fn exp_series_f128(x: f128) -> f128 {
    let mut sum = 1.0_f128;
    let mut term = 1.0_f128;
    let mut n = 1_u32;
    while n <= 48 {
        term *= x / n as f128;
        sum += term;
        n += 1;
    }
    sum
}
#[inline(always)]
pub(crate) fn reduce_exp_f64(x: f64) -> (f64, i32) {
    let k = (x * LOG2_E_F64).round() as i32;
    let kd = k as f64;
    let r = (x - kd * LN_2_HI_F64) - kd * LN_2_LO_F64;
    (r, k)
}
#[inline(always)]
pub(crate) fn reduce_exp_f32(x: f32) -> (f32, i32) {
    let k = ((x as f64) * LOG2_E_F64).round() as i32;
    let kd = k as f64;
    let r = ((x as f64 - kd * LN_2_HI_F64) - kd * LN_2_LO_F64) as f32;
    (r, k)
}
#[inline(always)]
fn exp_reduced_f64(x: f64) -> f64 {
    let (r, k) = reduce_exp_f64(x);
    k_simple_f64(r) * scale_pow2_f64(k)
}
#[inline(always)]
fn exp_reduced_f32(x: f32) -> f32 {
    let (r, k) = reduce_exp_f32(x);
    k_simple_f32(r) * scale_pow2_f32(k)
}
#[inline(always)]
fn exp_reduced_f128(x: f128) -> f128 {
    let k = (x * LOG2_E_F128).round() as i32;
    let kd = k as f128;
    let r = ((x - kd * LN_2_HI_F128) - kd * LN_2_MID_F128) - kd * LN_2_LO_F128;
    let y = exp_series_f128(r);
    if k == 16384 {
        (y * scale_pow2_f128(16383)) * 2.0_f128
    } else {
        y * scale_pow2_f128(k)
    }
}

#[inline]
pub fn exp(x: f64) -> f64 {
    if x.is_nan() {
        return f64::NAN;
    }
    if x == f64::INFINITY {
        return f64::INFINITY;
    }
    if x == f64::NEG_INFINITY {
        return 0.0_f64;
    }
    if x > EXP_MAX_F64 {
        return f64::INFINITY;
    }
    if x < EXP_MIN_F64 {
        return 0.0_f64;
    }
    exp_reduced_f64(x)
}

#[inline]
pub fn expl(x: f128) -> f128 {
    if x.is_nan() {
        return f128::NAN;
    }
    if x == f128::INFINITY {
        return f128::INFINITY;
    }
    if x == f128::NEG_INFINITY {
        return 0.0_f128;
    }
    if x > EXP_MAX_F128 {
        return f128::INFINITY;
    }
    if x < EXP_MIN_F128 {
        return 0.0_f128;
    }
    exp_reduced_f128(x)
}

#[inline]
pub fn expf(x: f32) -> f32 {
    if x.is_nan() {
        return f32::NAN;
    }
    if x == f32::INFINITY {
        return f32::INFINITY;
    }
    if x == f32::NEG_INFINITY {
        return 0.0_f32;
    }
    if x > EXP_MAX_F32 {
        return f32::INFINITY;
    }
    if x < EXP_MIN_F32 {
        return 0.0_f32;
    }
    exp_reduced_f32(x)
}

#[inline]
pub fn exps(x: f16) -> f16 {
    let x32 = x as f32;
    if x32.is_nan() {
        return f16::NAN;
    }
    if x32 == f32::INFINITY {
        return f16::INFINITY;
    }
    if x32 == f32::NEG_INFINITY {
        return 0.0_f16;
    }
    let k = (x32 * LOG2_E_F32).round() as i32;
    let r = (x32 - (k as f32) * LN_2_F32) as f16;
    k_simple_f16(r) * (scale_pow2_f32(k) as f16)
}

#[cfg(feature = "mx")]
#[inline]
pub fn exp_fp4_e2m1(x: Fp4E2M1) -> Fp4E2M1 {
    let x = f32::from(x);
    if !x.is_finite() {
        return Fp4E2M1::from(f32::NAN);
    }
    if x > EXP_MAX_F32 {
        return Fp4E2M1::from(f32::INFINITY);
    }
    if x < EXP_MIN_F32 {
        return Fp4E2M1::from(0.0_f32);
    }
    let k = (x * LOG2_E_F32).round() as i32;
    let r = Fp4E2M1::from(x - (k as f32) * LN_2_F32);
    k_simple_fp4_e2m1(r) * Fp4E2M1::from(scale_pow2_f32(k))
}

